}

message BackupIncreInfo
{
	optional ErrCode errcode= 1;
	optional int32 backup_full_cap = 2;
	optional int32 backup_bat_per = 3;
	optional int32 backup_discharge_rmain_bat_cap = 4;
	optional int32 cur_discharge_soc = 5;
